-- The real fleet (Mercuri International, offer 77, Ece Saray Marina, Fethiye) replaces the sample boats.
-- Plan: docs/plans/fleet-fethiye.md. Rows come in the next migration, generated by web/scripts/build_fleet_seed.py.

-- 1. yachts: what the new boat pages show.
alter table public.yachts
  add column name text,                                      -- 'Gusto 7'; null on the old sample rows
  add column marina text,                                    -- 'Ece Saray Marina'; base stays the town ('Fethiye, Türkiye')
  add column kind text not null default 'monohull' check (kind in ('monohull', 'catamaran')),
  add column engines integer not null default 1 check (engines between 1 and 2),  -- engine_hp is per engine
  add column skipper_cabin boolean not null default false,   -- the "+ 1" in "4 + 1 cabins"
  add column extra_berths integer not null default 0 check (extra_berths >= 0),  -- saloon and skipper berths: "8 + 2"
  add column max_guests integer,
  add column water_l integer,
  add column fuel_l integer,
  add column highlights text[] not null default '{}',        -- equipment worth naming: 'Twin wheels', 'Bow thruster'
  add column gallery jsonb not null default '[]',            -- [{photo_id, shape: 'l'|'p', caption}], as on courses
  add column layout_photo_id text,                           -- deck plan
  add column service_pack_eur integer,
  add column deposit_eur integer,
  add column extras jsonb not null default '[]',             -- [{name, note, price_eur, unit: 'day'|'week'|'booking'|'trip'}]
  add column published boolean not null default true;

-- 13.91 m, 7.96 m and 1.25 m need two decimals.
alter table public.yachts
  alter column length_m type numeric(5, 2),
  alter column beam_m type numeric(4, 2),
  alter column draft_m type numeric(4, 2);

comment on column public.yachts.translations is 'Text in other languages: used_for, photo_alt, description, highlights, gallery captions, extras.';
comment on column public.yachts.published is 'Shown on the site. Unpublished rows are invisible to the public key.';

-- The public key sees published boats only, so a hidden boat disappears everywhere at once.
drop policy "Anyone can read yachts" on public.yachts;
create policy "Anyone can read published yachts" on public.yachts for select to anon, authenticated using (published);

-- 2. Weekly charter prices by season, one row per boat and period.
create table public.yacht_prices (
  yacht_id uuid not null references public.yachts (id) on delete cascade,
  starts_on date not null,
  ends_on date not null,
  week_eur integer not null check (week_eur > 0),
  updated_at timestamptz not null default now(),
  primary key (yacht_id, starts_on),
  check (ends_on >= starts_on)
);
comment on table public.yacht_prices is 'Charter fee for the boat, one week Saturday to Saturday, by season (NauSYS list prices).';
alter table public.yacht_prices enable row level security;
create policy "Anyone can read yacht prices" on public.yacht_prices for select to anon, authenticated
  using (exists (select 1 from public.yachts y where y.id = yacht_id and y.published));
grant select on public.yacht_prices to anon, authenticated;

-- 3. Where a boat comes from. Not for the site: no read policy, no grants.
create table public.yacht_sources (
  yacht_id uuid primary key references public.yachts (id) on delete cascade,
  operator text not null,
  nausys_id bigint not null unique,
  offer_ref text,
  agent_discount_pct numeric(4, 1),
  updated_at timestamptz not null default now()
);
comment on table public.yacht_sources is 'Charter operator, NauSYS id and our agent discount. Editors only.';
alter table public.yacht_sources enable row level security;
revoke all on public.yacht_sources from anon, authenticated;

-- 4. Course dates point at a boat by slug, not by model text (two boats can share a model).
alter table public.course_dates
  add column yacht_slug text references public.yachts (slug) on update cascade;

drop function public.course_dates_live(text);
create function public.course_dates_live(p_slug text)
returns table (id uuid, key text, course_slug text, starts_on date, ends_on date, area text, boat text, meeting_point text,
               price_eur integer, places_total integer, places_left integer, yacht_slug text)
language sql stable security definer set search_path = '' as $$
  select d.id, d.key, d.course_slug, d.starts_on, d.ends_on, d.area, d.boat, d.meeting_point, d.price_eur, d.places_total,
         d.places_total - d.places_held - public.taken_course(d.id), d.yacht_slug
  from public.course_dates d where d.course_slug = p_slug order by d.starts_on
$$;
grant execute on function public.course_dates_live(text) to anon, authenticated;

-- 5. Freshness, as on every content table: updated_at and the revalidate call.
create trigger touch_updated_at before update on public.yacht_prices for each row execute function private.touch_updated_at();
create trigger touch_updated_at before update on public.yacht_sources for each row execute function private.touch_updated_at();
create trigger revalidate_site after insert or update or delete or truncate on public.yacht_prices
  for each statement execute function private.revalidate_site();
